using System.Net;
using System.Net.Sockets;
using System.Security.Cryptography;
using System.Text;

using var httpClient = new HttpClient(ProxyHandler());

var json = await httpClient.GetStringAsync(
    "https://tantabus.ai/api/v1/json/profiles/412");

using var mlDsa = MLDsa.ImportMLDsaPublicKey(MLDsaAlgorithm.MLDsa87, Convert.FromBase64String(""));

var message = Encoding.UTF8.GetBytes("My https://tantabus.ai/ username is Pipette Poster");
var signature = Convert.FromBase64String("");

await File.WriteAllTextAsync(
    "output.txt",
    json + "\n" +
    "\n" +
    mlDsa.VerifyData(message, signature) + "\n" +
    Convert.ToHexStringLower(SHA256.HashData(signature)) + "\n");

SocketsHttpHandler ProxyHandler()
{
    return new SocketsHttpHandler()
    {
        ConnectCallback = async (context, cancellationToken) =>
        {
            var socket = new Socket(SocketType.Stream, ProtocolType.Tcp);

            await socket.ConnectAsync(
                new DnsEndPoint(
                    Environment.GetEnvironmentVariable("PROXY_HOST"),
                    int.Parse(Environment.GetEnvironmentVariable("PROXY_PORT"))),
                cancellationToken);

            return new NetworkStream(socket, ownsSocket: true);
        }
    };
}
